begin;
create table if not exists public.mme_treasury_bank_accounts(bank_account_id uuid primary key default gen_random_uuid(),account_code text not null unique,bank_name text not null,account_name text not null,account_type text not null check(account_type in('checking','savings','money_market','sweep','other')),currency char(3) not null default 'USD',account_last4 char(4),routing_last4 char(4),entity_id uuid references public.mme_financial_reporting_entities(entity_id),opening_balance numeric(16,2) not null default 0,account_status text not null default 'active' check(account_status in('active','restricted','closed')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(account_last4 is null or account_last4 ~ '^[0-9]{4}$'),check(routing_last4 is null or routing_last4 ~ '^[0-9]{4}$'));
create table if not exists public.mme_treasury_bank_transactions(bank_transaction_id uuid primary key default gen_random_uuid(),bank_account_id uuid not null references public.mme_treasury_bank_accounts(bank_account_id),provider_reference text not null,transaction_date date not null,description text not null,amount numeric(16,2) not null,currency char(3) not null default 'USD',transaction_type text not null check(transaction_type in('credit','debit')),transaction_status text not null default 'unreconciled' check(transaction_status in('unreconciled','matched','exception','reconciled')),source_system text not null default 'manual_import',import_batch_id uuid,created_at timestamptz not null default now(),unique(bank_account_id,provider_reference));
create table if not exists public.mme_treasury_reconciliations(reconciliation_id uuid primary key default gen_random_uuid(),bank_transaction_id uuid not null references public.mme_treasury_bank_transactions(bank_transaction_id),gl_reference text,matched_amount numeric(16,2) not null,variance_amount numeric(16,2) not null default 0,match_status text not null check(match_status in('matched','exception')),reviewed_by_auth_user_id uuid not null,review_note text,reviewed_at timestamptz not null default now(),unique(bank_transaction_id));
create table if not exists public.mme_treasury_cash_positions(cash_position_id uuid primary key default gen_random_uuid(),bank_account_id uuid not null references public.mme_treasury_bank_accounts(bank_account_id),as_of_date date not null,available_balance numeric(16,2) not null,ledger_balance numeric(16,2) not null,currency char(3) not null default 'USD',source_system text not null,source_reference text,recorded_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(bank_account_id,as_of_date,source_system));
create table if not exists public.mme_treasury_cash_forecasts(cash_forecast_id uuid primary key default gen_random_uuid(),forecast_name text not null,scenario text not null check(scenario in('base','upside','downside','custom')),period_start date not null,period_end date not null,currency char(3) not null default 'USD',opening_cash numeric(16,2) not null,inflows numeric(16,2) not null default 0,outflows numeric(16,2) not null default 0,projected_closing_cash numeric(16,2) generated always as(opening_cash+inflows-outflows) stored,assumptions jsonb not null default '{}'::jsonb,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(period_end>=period_start),check(inflows>=0 and outflows>=0));
create table if not exists public.mme_treasury_check_register(check_id uuid primary key default gen_random_uuid(),bank_account_id uuid not null references public.mme_treasury_bank_accounts(bank_account_id),check_number text not null,payee text not null,issue_date date not null,amount numeric(16,2) not null check(amount>0),currency char(3) not null default 'USD',check_status text not null default 'outstanding' check(check_status in('outstanding','cleared','void','stop_payment')),cleared_date date,source_reference text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(bank_account_id,check_number));
create table if not exists public.mme_treasury_ach_settlements(ach_settlement_id uuid primary key default gen_random_uuid(),provider_reference text not null unique,bank_account_id uuid not null references public.mme_treasury_bank_accounts(bank_account_id),settlement_date date not null,amount numeric(16,2) not null check(amount<>0),currency char(3) not null default 'USD',settlement_status text not null default 'imported' check(settlement_status in('imported','pending','settled','returned','exception')),source_system text not null,source_reference text,created_at timestamptz not null default now());
create index if not exists mme_treasury_transactions_date_idx on public.mme_treasury_bank_transactions(bank_account_id,transaction_date desc);
create index if not exists mme_treasury_cash_position_date_idx on public.mme_treasury_cash_positions(as_of_date desc);
create index if not exists mme_treasury_forecast_period_idx on public.mme_treasury_cash_forecasts(period_start,period_end);
create or replace function public.mme_treasury_reconcile_transaction(p_transaction uuid,p_gl_reference text,p_matched_amount numeric,p_actor uuid,p_note text) returns uuid language plpgsql security definer set search_path=public as $$declare t public.mme_treasury_bank_transactions%rowtype;rid uuid;v numeric;begin select * into t from public.mme_treasury_bank_transactions where bank_transaction_id=p_transaction for update;if not found or t.transaction_status='reconciled' then raise exception 'transaction_not_reconcilable';end if;if p_matched_amount is null then raise exception 'matched_amount_required';end if;v:=t.amount-p_matched_amount;insert into public.mme_treasury_reconciliations(bank_transaction_id,gl_reference,matched_amount,variance_amount,match_status,reviewed_by_auth_user_id,review_note) values(p_transaction,p_gl_reference,p_matched_amount,v,case when v=0 then 'matched' else 'exception' end,p_actor,left(coalesce(p_note,''),1000)) returning reconciliation_id into rid;update public.mme_treasury_bank_transactions set transaction_status=case when v=0 then 'reconciled' else 'exception' end where bank_transaction_id=p_transaction;return rid;end$$;
do $$declare t text;begin foreach t in array array['mme_treasury_bank_accounts','mme_treasury_bank_transactions','mme_treasury_reconciliations','mme_treasury_cash_positions','mme_treasury_cash_forecasts','mme_treasury_check_register','mme_treasury_ach_settlements'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on function public.mme_treasury_reconcile_transaction(uuid,text,numeric,uuid,text) from public,anon,authenticated;
grant execute on function public.mme_treasury_reconcile_transaction(uuid,text,numeric,uuid,text) to service_role;
commit;